<!--
 * 消息发送记录列表页组件
 *
 * @path apps/message-web/src/views/message/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（pageLog 发送日志分页 + 发送消息弹窗）。
-->
<script lang="ts" setup>
/**
 * 消息发送（列表页）
 * <p>消费后端契约 MessageController（src/api/message.ts，auto-generated by bash/gen-contract.py）：
 * pageLog() 分页查询消息发送日志；工具栏「发送消息」打开 message-form.vue 发起新消息。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElTag } from 'element-plus';
import { h } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { pageLog } from '#/api/message';
import type { MsgLogVO } from '#/api/models';

import MessageForm from './message-form.vue';

defineOptions({ name: 'MessageManagement' });

/** 状态列 Tag 类型映射（兼容字符串/数字取值，未知值按 info 展示） */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SUCCESS', 'SENT', 'DELIVERED'].includes(upper)) return 'success';
  if (['FAILED', 'DEAD', 'ERROR'].includes(upper)) return 'danger';
  if (['SENDING', 'PENDING', 'RETRY', 'RECALL'].includes(upper)) return 'warning';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgLogVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'msgId', title: '消息ID', width: 180 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'bizType', title: '业务类型', width: 110 },
    { field: 'receiver', title: '接收者', width: 150 },
    { field: 'templateCode', title: '模板编码', width: 150 },
    {
      field: 'status',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: getStatusType(row.status) }, () => row.status ?? '-'),
      },
    },
    { field: 'priority', title: '优先级', width: 90 },
    { field: 'costMs', title: '耗时(ms)', width: 90 },
    { field: 'createdAt', title: '创建时间', width: 170 },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await pageLog({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'Input', props: { placeholder: '通道' } },
      },
      {
        field: 'bizType',
        title: '业务类型',
        itemRender: { name: 'Input', props: { placeholder: '业务类型' } },
      },
      {
        field: 'status',
        title: '状态',
        itemRender: { name: 'Input', props: { placeholder: '状态' } },
      },
      {
        field: 'keyword',
        title: '关键词',
        itemRender: { name: 'Input', props: { placeholder: '关键词' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [MessageFormModal, messageFormApi] = useYDSZModal({ connectedComponent: MessageForm });

function handleSend() {
  messageFormApi.open();
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="消息发送日志">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleSend">发送消息</ElButton>
      </template>
    </Grid>
    <MessageFormModal @success="gridApi.query()" />
  </Page>
</template>
